import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    E = []
    for _ in range(N):
        E.append(int(next(iterator)))

    adj = [[] for _ in range(N)]
    indegree = [0] * N

    for _ in range(M):
        t1 = int(next(iterator))
        t2 = int(next(iterator))
        adj[t2].append(t1)
        indegree[t1] += 1

    dp = [0] * N
    queue = deque()

    for i in range(N):
        if indegree[i] == 0:
            if E[i] == 1:
                dp[i] = 1
            else:
                dp[i] = 0
            queue.append(i)

    while queue:
        u = queue.popleft()

        for v in adj[u]:
            if E[v] == 1:
                if dp[u] == 0:
                    new_val = dp[u] + 1
                else:
                    new_val = dp[u]
                if new_val > dp[v]:
                    dp[v] = new_val
            else:
                new_val = dp[u]
                if new_val > dp[v]: dp[v] = new_val

            indegree[v] -= 1
            if indegree[v] == 0:
                queue.append(v)

    if N > 0:
        print(max(dp))
    else:
        print(0)

if __name__ == "__main__":
    solve()
